import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for ``key`` in ``name=value`` per-line config text.

    Rules:
    - Each line is ``name=value``; the first ``=`` separates name from value.
    - Whitespace around the name and the value is stripped.
    - Blank lines and lines whose first non-space character is ``#`` are ignored.
    - Lines without ``=`` are ignored.
    - If ``key`` appears more than once, the first occurrence wins.
    - If ``key`` is absent, return an empty string.
    - The text is a parameter; this function never reads files.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_returns_value_for_present_key() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_returns_empty_string_when_key_absent() -> None:
    assert config_value("host=localhost", "port") == ""


def test_returns_empty_string_for_empty_text() -> None:
    assert config_value("", "host") == ""


def test_strips_whitespace_around_name_and_value() -> None:
    assert config_value("  host  =   example.com  ", "host") == "example.com"


def test_ignores_comment_and_blank_lines() -> None:
    text = "# host=wrong\n\n   # port=1\nhost=right"
    assert config_value(text, "host") == "right"
    assert config_value(text, "port") == ""


def test_ignores_lines_without_equals() -> None:
    assert config_value("novalue\nname=ok", "name") == "ok"
    assert config_value("novalue", "novalue") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("k=1\nk=2", "k") == "1"


def test_value_may_contain_equals_sign() -> None:
    assert config_value("expr=a=b", "expr") == "a=b"


def test_empty_value_is_returned_as_empty_string() -> None:
    assert config_value("key=", "key") == ""
